// Original instrumental soundscapes. No anthem recordings, lyrics, video or network media.
const compositions={bernabeu:['银色序曲',48,88,'glow'],campnou:['红蓝微光',50,92,'glow'],anfield:['红色回声',45,90,'warm'],allianz:['夜色脉冲',48,100,'pulse'],sansiro:['米兰夜行',43,86,'warm'],oldtrafford:['归家的灯',48,88,'warm'],dortmund:['黄墙心跳',50,104,'pulse'],paris:['巴黎暮色',46,88,'glow'],emirates:['北伦敦余晖',48,94,'warm'],juventus:['黑白之间',45,96,'pulse'],etihad:['天空蓝时刻',50,94,'glow'],tottenham:['未来轮廓',48,100,'glow'],stamfordbridge:['蓝色街角',43,90,'warm'],metropolitano:['红白律动',45,102,'pulse'],dragao:['巨龙的风',50,90,'glow'],luz:['光明之前',48,94,'warm'],galatasaray:['金色看台',46,102,'pulse'],cruyff:['自由的线条',50,96,'glow'],feyenoord:['港城回响',43,98,'pulse'],celtic:['绿色归途',48,88,'warm'],bombonera:['蓝金心跳',45,104,'pulse'],monumental:['长夜的看台',48,96,'warm'],maracana:['里约晚风',50,100,'glow'],napoli:['天蓝的海',45,88,'warm']};
export const tracks=Object.fromEntries(Object.entries(compositions).map(([id,[name,root,bpm,style]],i)=>[id,{name,root,bpm,style,seed:i+1,credit:'看台之外 · 原创足球氛围音乐',original:true}]));

export class MatchdayAudio{
 constructor(update,{muted=false}={}){this.update=update;this.muted=muted;this.ctx=null;this.token=0;this.nodes=new Set();this.active=false;this.state='idle';this.timer=null;this.suspendTimer=null;this.bus=null;}
 emit(state,message){this.state=state;this.update({state,message,muted:this.muted,track:this.track?.name});}
 init(){if(this.ctx)return;const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)throw new Error('unsupported');this.ctx=new Audio();this.master=this.ctx.createGain();this.master.gain.value=this.muted?0:.075;const compressor=this.ctx.createDynamicsCompressor();compressor.threshold.value=-20;compressor.knee.value=16;compressor.ratio.value=3;compressor.attack.value=.015;compressor.release.value=.3;this.master.connect(compressor);compressor.connect(this.ctx.destination);const length=Math.floor(this.ctx.sampleRate*1.1);this.noise=this.ctx.createBuffer(1,length,this.ctx.sampleRate);const d=this.noise.getChannelData(0);let value=0;for(let i=0;i<length;i++){value=(value+(Math.random()*2-1)*.045)/1.025;d[i]=value*3;}}
 mount(track){this.stopTrack(.45);clearTimeout(this.suspendTimer);this.active=true;this.track=track;const token=++this.token;try{this.init();const attempt=this.ctx.resume();this.emit('starting',this.muted?'原创氛围音乐已静音':'原创氛围音乐正在缓缓入场');Promise.resolve(attempt).then(()=>{if(token!==this.token||!this.active)return;if(this.ctx.state!=='running'){this.emit('blocked','浏览器暂时限制了有声播放');return;}this.begin(track);this.emit('playing',this.muted?'原创氛围音乐已静音':'原创氛围音乐正在低音量播放');}).catch(()=>{if(token===this.token)this.emit('blocked','浏览器暂时限制了有声播放');});}catch{this.emit('unavailable','当前浏览器暂不支持背景音乐');}}
 begin(track){const c=this.ctx,t=c.currentTime;this.bus=c.createGain();this.bus.gain.setValueAtTime(0,t);this.bus.gain.linearRampToValueAtTime(1,t+3.6);this.filter=c.createBiquadFilter();this.filter.type='lowpass';this.filter.frequency.value=track.style==='glow'?1700:1200;this.filter.Q.value=.3;this.filter.connect(this.bus);this.bus.connect(this.master);this.beat=0;this.nextBeat=t+.04;this.schedule();this.timer=setInterval(()=>this.schedule(),120);}
 schedule(){if(!this.active||!this.ctx||this.ctx.state!=='running'||!this.bus)return;const step=60/this.track.bpm;while(this.nextBeat<this.ctx.currentTime+.4){this.writeBeat(this.beat,this.nextBeat,step);this.beat++;this.nextBeat+=step;}}
 keep(node){this.nodes.add(node);node.onended=()=>{this.nodes.delete(node);try{node.disconnect();}catch{}};return node;}
 tone(note,start,duration,gain,{type='sine',pan=0,attack=.07,detune=0}={}){const c=this.ctx,osc=this.keep(c.createOscillator()),env=c.createGain(),panner=c.createStereoPanner();osc.type=type;osc.frequency.value=440*2**((note-69)/12);osc.detune.value=detune;panner.pan.value=pan;env.gain.setValueAtTime(0,start);env.gain.linearRampToValueAtTime(gain,start+attack);env.gain.setValueAtTime(gain*.72,start+Math.max(attack,duration*.55));env.gain.exponentialRampToValueAtTime(.0001,start+duration);osc.connect(env);env.connect(panner);panner.connect(this.filter);osc.addEventListener('ended',()=>{env.disconnect();panner.disconnect();});osc.start(start);osc.stop(start+duration+.03);}
 writeBeat(beat,t,step){const tr=this.track,bar=Math.floor(beat/4),position=beat%4,progression=[0,5,9,7],chordIndex=Math.floor(bar/2)%4,root=tr.root+progression[chordIndex],scale=[0,2,4,7,9];if(position===0){for(let i=0;i<3;i++){const note=root+(chordIndex===2?[0,3,7]:[0,4,7])[i]+12;this.tone(note,t,step*4.7,.072,{type:'sine',pan:(i-1)*.32,attack:.8,detune:-4});this.tone(note,t+.025,step*4.5,.018,{type:'triangle',pan:(i-1)*.2,attack:.95,detune:4});}this.tone(root-12,t,step*3.8,.12,{attack:.15});}const pattern=(beat+tr.seed*3)%16;if([0,3,6,10,13].includes(pattern)){const degree=scale[(Math.floor(beat/3)+tr.seed)%scale.length];this.tone(tr.root+24+degree,t+step*.08,step*1.6,tr.style==='glow'?.042:.028,{type:'triangle',pan:Math.sin(beat*.45)*.35,attack:.05});}if(position===0||tr.style==='pulse'&&position===2){const c=this.ctx,o=this.keep(c.createOscillator()),g=c.createGain();o.frequency.setValueAtTime(96,t);o.frequency.exponentialRampToValueAtTime(44,t+.2);g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(tr.style==='pulse'?.32:.18,t+.012);g.gain.exponentialRampToValueAtTime(.0001,t+.32);o.connect(g);g.connect(this.bus);o.addEventListener('ended',()=>g.disconnect());o.start(t);o.stop(t+.34);}if(position===2){const c=this.ctx,n=this.keep(c.createBufferSource()),g=c.createGain(),f=c.createBiquadFilter();n.buffer=this.noise;f.type='bandpass';f.frequency.value=1050;f.Q.value=.65;g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(.085,t+.018);g.gain.exponentialRampToValueAtTime(.0001,t+.22);n.connect(f);f.connect(g);g.connect(this.bus);n.addEventListener('ended',()=>{f.disconnect();g.disconnect();});n.start(t);n.stop(t+.24);}}
 toggleMute(){this.muted=!this.muted;if(this.ctx&&this.master){const t=this.ctx.currentTime;this.master.gain.cancelScheduledValues(t);this.master.gain.setValueAtTime(this.master.gain.value,t);this.master.gain.linearRampToValueAtTime(this.muted?0:.075,t+(this.muted?.25:1.1));if(!this.muted&&this.active)this.resume();}this.update({state:this.state,muted:this.muted,message:this.muted?'背景音乐已静音':'背景音乐已开启'});return this.muted;}
 pause(){if(!this.ctx||!this.active)return;clearInterval(this.timer);const token=this.token;this.ctx.suspend().then(()=>{if(token===this.token&&this.active&&this.ctx.state==='suspended')this.emit('paused','页面离开时背景音乐已暂停');}).catch(()=>{});}
 resume(){if(!this.ctx||!this.active)return;const token=this.token;this.ctx.resume().then(()=>{if(token!==this.token||!this.active)return;clearInterval(this.timer);if(!this.bus)this.begin(this.track);else{this.nextBeat=Math.max(this.nextBeat,this.ctx.currentTime+.04);this.schedule();this.timer=setInterval(()=>this.schedule(),120);}this.emit('playing',this.muted?'背景音乐已静音':'原创氛围音乐正在低音量播放');}).catch(()=>{if(token===this.token)this.emit('blocked','浏览器暂时限制了有声播放');});}
 stopTrack(fade=.3){clearInterval(this.timer);if(!this.ctx)return;const t=this.ctx.currentTime;if(this.bus){const old=this.bus;old.gain.cancelScheduledValues(t);old.gain.setValueAtTime(old.gain.value,t);old.gain.linearRampToValueAtTime(0,t+fade);setTimeout(()=>{try{old.disconnect();}catch{}},fade*1000+50);}for(const n of this.nodes){try{n.stop(t+fade+.02);}catch{}}this.nodes.clear();this.bus=null;}
 destroy(){this.active=false;this.token++;this.stopTrack(.35);const token=this.token;clearTimeout(this.suspendTimer);if(this.ctx)this.suspendTimer=setTimeout(()=>{if(token===this.token&&!this.active)this.ctx.suspend().catch(()=>{});},450);this.emit('idle','背景音乐已停止');}
}
